    if len(raw) > 1048576:
        raise ValueError('bundle')
    print(json.dumps(install_runner(json.loads(raw))), flush=True)

try:
    installer_main()
except (ValueError, OSError, KeyError, TypeError, subprocess.SubprocessError):
