    password = base64.urlsafe_b64encode(hmac.new(key,
        ('3x-ui/admin/' + job_id).encode(), hashlib.sha256).digest()).decode().rstrip('=')
    path_file = DATABASE / '.antirkn-webpath'
    base_path = '/'
    if path_file.exists():
        safe_file(path_file, 128)
        base_path = path_file.read_text()
