    """Install the unmodified, pinned upstream menu without running install.sh."""
    if CLI.exists() or CLI.is_symlink():
        safe_file(CLI, 1024 * 1024)
        if not os.access(CLI, os.X_OK): raise PanelError('panel_conflict')
