                raw = response.read(RELEASE['cli']['bytes'] + 1)
        except OSError as error:
            raise PanelError('panel_download_failed') from error
    if len(raw) != RELEASE['cli']['bytes'] or hashlib.sha256(raw).hexdigest() != RELEASE['cli']['sha256']:
